mapper.select:
SELECT a.id AS atlas_id, a.atlas_code, a.image_url AS atlas_image_url, a.species_id, s.herb_name AS species_name, f.feature_vector FROM herb_atlas a INNER JOIN herb_species s ON s.id = a.species_id AND s.deleted = 0 INNER JOIN herb_atlas_feature f ON f.atlas_id = a.id AND f.deleted = 0 AND f.extract_status = 'success' AND f.create_time = ( SELECT MAX(ff.create_time) FROM herb_atlas_feature ff WHERE ff.atlas_id = a.id AND ff.deleted = 0 AND ff.extract_status = 'success' ) WHERE a.deleted = 0 AND a.status = 1 AND f.feature_vector IS NOT NULL AND f.feature_vector != ''
AND a.species_id = #{speciesId}
ORDER BY a.id ASC

SELECT COUNT(1)
FROM herb_image_match m
INNER JOIN herb_image i ON i.id = m.image_id AND i.deleted = 0
INNER JOIN herb_atlas a ON a.id = m.atlas_id AND a.deleted = 0
LEFT JOIN herb_species s ON s.id = a.species_id AND s.deleted = 0

    m.deleted = 0

        AND m.image_id = #{query.imageId}


        AND m.atlas_id = #{query.atlasId}


        AND a.species_id = #{query.speciesId}


        AND m.match_result = #{query.matchResult}


        AND m.similarity_score >= #{query.minSimilarity}


        AND m.similarity_score <= #{query.maxSimilarity}


        AND m.create_time >= #{query.startTime}


        AND m.create_time <= #{query.endTime}

SELECT

FROM herb_image_match m
INNER JOIN herb_image i ON i.id = m.image_id AND i.deleted = 0
INNER JOIN herb_atlas a ON a.id = m.atlas_id AND a.deleted = 0
LEFT JOIN herb_species s ON s.id = a.species_id AND s.deleted = 0

    m.deleted = 0

        AND m.image_id = #{query.imageId}


        AND m.atlas_id = #{query.atlasId}


        AND a.species_id = #{query.speciesId}


        AND m.match_result = #{query.matchResult}


        AND m.similarity_score >= #{query.minSimilarity}


        AND m.similarity_score <= #{query.maxSimilarity}


        AND m.create_time >= #{query.startTime}


        AND m.create_time <= #{query.endTime}


ORDER BY m.match_time DESC, m.create_time DESC, m.match_rank ASC
LIMIT #{offset}, #{pageSize}
